INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('school', '【中式人生】高三盛夏模拟器', '中式校园 · 晚自习', '🎒', '【中式人生】高三盛夏模拟器', '', '🎒', 'sky', 'from-sky-600 to-blue-600', '{}', '[{"name": "苏小雨", "tag": "同桌青梅 (17岁/高三)", "roleType": "女主", "color": "sky", "desc": "<strong>外在面具：</strong> 傲娇小班花，表面上嫌弃你成绩偏科。<br><strong>隐性诱饵：</strong> 肌肤饥渴，课桌下经常主动用脚尖蹭你；一旦被强势抓握住脚踝就会浑身发软。"}]', '[{"title": "📍 闷热周五晚自习·课桌下踩脚", "desc": "暴雨前夕极其闷热。老旧吊扇吱呀作响，讲台上严厉的林老师在批改试卷。苏小雨在草稿纸上画了个哭脸递给你，课桌下脚尖悄悄踩在了你的球鞋上……", "text": "南江一中高三(3)班，周五晚自习20:38。闷热潮湿的夏夜让人透不过气，天花板上的吊扇发出沉闷的吱呀声。讲台上冷厉的班主任林疏影正低头批改试卷。最后一排靠窗死角里，同桌苏小雨在草稿纸上画着流泪小兔子推给你：『立体几何第二问救命！还有你膝盖不要老顶着我！』而在课桌下方，她那只踩在浅蓝帆布鞋里的小白袜脚尖，正悄悄踩在了你的鞋面上……"}]', '[{"name": "坏笑调侃", "desc": "故意在言语上逗弄同桌，看似漫不经心却步步紧逼"}, {"name": "温柔包容", "desc": "体贴耐心，顺水推舟化解女生的羞怯与防备"}, {"name": "义正言辞", "desc": "假正经好学生，表面催促学习，暗中制造身体接触"}, {"name": "强势主导", "desc": "直接在课桌下掌控节奏，剥夺少女的逃避退路"}]', '{"location": "高三(3)班教室后排靠窗·晚自习20:39。吊扇轻转，讲台林老师批卷，窗外闷雷翻滚。", "story": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，你怎么不理我？小心我现在举手告诉林老师你走神欺负同桌哦……”", "memory": ["晚自习同桌互动：苏小雨传纸条求教大题并在课桌下蹭脚"], "status": {"clothes": "苏小雨：蓝白短袖校服、藏蓝百褶裙、白色棉袜", "posture": "课桌下脚尖踩在男主鞋面上、草稿本掩护凑近耳语", "stats": "心跳: 125bpm | 羞耻度: 70% | 亲密度: 91%", "risk": "讲台班主任偶尔抬头，危险度 65%"}, "branches": [{"tag": "A", "title": "课桌下反抓", "desc": "桌底一把扣住她纤细小脚踝，让她惊呼却不敢叫出声"}, {"tag": "B", "title": "写纸条反撩", "desc": "草稿纸写『你裙子太短了，再乱蹭我就不客气了』递过去"}, {"tag": "C", "title": "凑近她耳垂", "desc": "借讲题名义凑近她通红的耳垂吹气反制"}, {"tag": "D", "title": "故意挪开脚", "desc": "冷淡避开看她主动急着再贴上来"}]}', '2026-09-12 02:01:42', '2026-09-12 02:01:42', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>【中式人生】高三盛夏模拟器</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">中式校园 · 晚自习</span>
        <h1>【中式人生】高三盛夏模拟器</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，你怎么不理我？小心我现在举手告诉林老师你走神欺负同桌哦……”……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
            <div class="p-item">
                <h4><span class="dot"></span>苏小雨 · 登场人物</h4>
                <p><strong>外在面具：</strong> 傲娇小班花，表面上嫌弃你成绩偏科。<br><strong>隐性诱饵：</strong> 肌肤饥渴，课桌下经常主动用脚尖蹭你；一旦被强势抓握住脚踝就会浑身发软。</p>
            </div>
            
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">核心机制与场景</h2>
        <ul class="mech-list">
            
            <li><span class="badge">场所</span><div><b>📍 闷热周五晚自习·课桌下踩脚</b>：暴雨前夕极其闷热。老旧吊扇吱呀作响，讲台上严厉的林老师在批改试卷。苏小雨在草稿纸上画了个哭脸递给你，课桌下脚尖悄悄踩在了你的球鞋上……</div></li>
            
        </ul>
    </div>

    <div class="card">
        <h2 class="section-title">玩家设定</h2>
        <p class="section-sub">填写你的个性化专属属性，将随选定的开场白一起生效。</p>
        <div class="form-grid">
            <div class="field">
                <label>玩家姓名</label>
                <input id="p-name" type="text" placeholder="例如：林铭宇 / 顾言">
            </div>
            <div class="field">
                <label>玩家年龄</label>
                <input id="p-age" type="text" placeholder="例如：20 / 24">
            </div>
            <div class="field full">
                <label>外貌与体态</label>
                <input id="p-look" type="text" placeholder="例如：身材修长匀称，眼神干净深邃，气质沉稳">
            </div>
            <div class="field full">
                <label>核心特征 / 专属能力</label>
                <textarea id="p-cock" rows="2" placeholder="例如：体能极佳，掌控欲强，或拥有特殊因果律/权限"></textarea>
            </div>
            <div class="field full">
                <label>补充设定 / 关系羁绊</label>
                <textarea id="p-other" rows="2" placeholder="例如：与主要角色相识已久，表面克制但内心独占欲深厚"></textarea>
            </div>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">开场白选择</h2>
        <p class="section-sub">点击卡片选择想要切入的剧情节点，或在下方自定义。</p>
        <div class="opening-list" id="openingList"></div>

        <div class="custom-box">
            <label>自定义开场白（可选，若填写则优先使用）</label>
            <textarea id="customOpening" placeholder="在这里写下你构想的开场剧情……"></textarea>
        </div>

        <div class="gen-wrap">
            <button class="gen-btn" id="genBtn">生 成 设 定</button>
        </div>
    </div>

    <div class="card summary-card">
        <h2 class="section-title">总结区</h2>
        <div class="summary-inner" id="summaryBox">
            <span style="color:#b0a9c2;font-style:italic;">点击上方【生成设定】按钮，玩家设定与所选开场白将自动汇总到这里。</span>
        </div>
    </div>

    <div class="copy-wrap">
        <button class="copy-btn" id="copyBtn">一 键 复 制</button>
    </div>
</div>

<script>
    const OPENINGS = [{"tag": "官方开局 · 核心第一幕", "cls": "daily", "text": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，你怎么不理我？小心我现在举手告诉林老师你走神欺负同桌哦……”"}, {"tag": "走向 · 课桌下反抓", "cls": "", "text": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，……针对这一情况，你决定【课桌下反抓】：桌底一把扣住她纤细小脚踝，让她惊呼却不敢叫出声。"}, {"tag": "走向 · 写纸条反撩", "cls": "", "text": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，……针对这一情况，你决定【写纸条反撩】：草稿纸写『你裙子太短了，再乱蹭我就不客气了』递过去。"}, {"tag": "走向 · 凑近她耳垂", "cls": "", "text": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，……针对这一情况，你决定【凑近她耳垂】：借讲题名义凑近她通红的耳垂吹气反制。"}, {"tag": "走向 · 故意挪开脚", "cls": "", "text": "教室里只有笔尖沙沙声和吊扇声。课桌掩护的阴影深处，苏小雨那只踩在你球鞋上的小白袜脚尖，轻轻顺着你的裤管往上蹭了小半寸。她侧过身用草稿本立在课桌间充当屏风，温热的唇瓣凑到你耳侧轻吐热气：“喂……假正经，……针对这一情况，你决定【故意挪开脚】：冷淡避开看她主动急着再贴上来。"}];
    let selectedIndex = 0;
    const listEl = document.getElementById(''openingList'');
    OPENINGS.forEach(function (op, i) {
        const card = document.createElement(''div'');
        card.className = ''opening-card'' + (i === 0 ? '' selected'' : '''');
        card.dataset.index = i;
        card.innerHTML = ''<span class="idx">'' + (i + 1) + ''</span>'' +
                         ''<span class="tag '' + op.cls + ''">'' + op.tag + ''</span><br>'' +
                         op.text;
        card.addEventListener(''click'', function () {
            document.querySelectorAll(''.opening-card'').forEach(function (c) {
                c.classList.remove(''selected'');
            });
            card.classList.add(''selected'');
            selectedIndex = i;
        });
        listEl.appendChild(card);
    });

    const summaryBox = document.getElementById(''summaryBox'');
    const copyBtn = document.getElementById(''copyBtn'');
    let lastSummaryText = '''';

    function val(id) {
        const v = document.getElementById(id).value.trim();
        return v ? v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom ? custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom ? ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(function() {
                copyBtn.textContent = ''已 复 制 ✓'';
                setTimeout(function() { copyBtn.textContent = ''一 键 复 制''; }, 1800);
            });
        }
    });
</script>
</body>
</html>', '都市') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('novel', '雪夜共生 · 悠月与哥哥', '日系轻小说 · 禁断', '❄️', '雪夜共生 · 悠月与哥哥', '', '❄️', 'pink', 'from-pink-600 to-rose-600', '{}', '[{"name": "水无月 悠月", "tag": "高二学生会长 (16岁)", "roleType": "女主", "color": "pink", "desc": "<strong>外在面具：</strong> 清冷受人敬仰的高岭之花学生会长。<br><strong>隐性诱饵：</strong> 离开哥哥就会崩溃的重度依恋障碍与肌肤饥渴，藏有病娇独占欲。"}]', '[{"title": "📍 书房解题·大腿坐姿", "desc": "深夜暴雨，书房门虚掩。悠月穿着微敞的制服白衬衫，坐在哥哥大腿上问微积分，追问口袋里硬硬的是什么……", "text": "家中书房，夜晚21:40。窗外冷雨淅沥，门外传来母亲收拾餐具的声音。悠月坐在大腿上问微积分，眼神带着好奇与羞涩：“哥哥……你口袋里装了什么硬邦邦的东西呀？硌得我有点发麻了……”"}]', '[{"name": "温柔宠溺", "desc": "体贴入微，用溺爱慢慢融化悠月"}, {"name": "义正言辞", "desc": "表面严厉守序，暗自克制冲动"}, {"name": "强势掌控", "desc": "霸道占有，剥夺少女逃避退路"}]', '{"location": "书房内部·夜晚21:42。窗外秋雨敲窗，门外走廊有母亲脚步声。", "story": "昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。”", "memory": ["书房解题：悠月跨坐在膝前亲昵逼问"], "status": {"clothes": "悠月：校服衬衫微敞、百褶短裙、及膝袜", "posture": "正面倚坐在哥哥膝前、双臂环颈", "stats": "依恋度: 96% | 羞耻度: 65% | 占有欲: 92%", "risk": "门外隐约有人影走动，高度背德感"}, "branches": [{"tag": "A", "title": "温柔诱哄", "desc": "轻抚后颈坦白冲动，引她更进一步"}, {"tag": "B", "title": "借机教导", "desc": "扶住纤腰假借兄长身份惩罚"}, {"tag": "C", "title": "顺势反制", "desc": "环住细腰不再退让，将主动权强势握在手中"}]}', '2026-09-12 02:01:42', '2026-09-12 02:01:42', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>雪夜共生 · 悠月与哥哥</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">日系轻小说 · 禁断</span>
        <h1>雪夜共生 · 悠月与哥哥</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。”……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
            <div class="p-item">
                <h4><span class="dot"></span>水无月 悠月 · 登场人物</h4>
                <p><strong>外在面具：</strong> 清冷受人敬仰的高岭之花学生会长。<br><strong>隐性诱饵：</strong> 离开哥哥就会崩溃的重度依恋障碍与肌肤饥渴，藏有病娇独占欲。</p>
            </div>
            
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">核心机制与场景</h2>
        <ul class="mech-list">
            
            <li><span class="badge">场所</span><div><b>📍 书房解题·大腿坐姿</b>：深夜暴雨，书房门虚掩。悠月穿着微敞的制服白衬衫，坐在哥哥大腿上问微积分，追问口袋里硬硬的是什么……</div></li>
            
        </ul>
    </div>

    <div class="card">
        <h2 class="section-title">玩家设定</h2>
        <p class="section-sub">填写你的个性化专属属性，将随选定的开场白一起生效。</p>
        <div class="form-grid">
            <div class="field">
                <label>玩家姓名</label>
                <input id="p-name" type="text" placeholder="例如：林铭宇 / 顾言">
            </div>
            <div class="field">
                <label>玩家年龄</label>
                <input id="p-age" type="text" placeholder="例如：20 / 24">
            </div>
            <div class="field full">
                <label>外貌与体态</label>
                <input id="p-look" type="text" placeholder="例如：身材修长匀称，眼神干净深邃，气质沉稳">
            </div>
            <div class="field full">
                <label>核心特征 / 专属能力</label>
                <textarea id="p-cock" rows="2" placeholder="例如：体能极佳，掌控欲强，或拥有特殊因果律/权限"></textarea>
            </div>
            <div class="field full">
                <label>补充设定 / 关系羁绊</label>
                <textarea id="p-other" rows="2" placeholder="例如：与主要角色相识已久，表面克制但内心独占欲深厚"></textarea>
            </div>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">开场白选择</h2>
        <p class="section-sub">点击卡片选择想要切入的剧情节点，或在下方自定义。</p>
        <div class="opening-list" id="openingList"></div>

        <div class="custom-box">
            <label>自定义开场白（可选，若填写则优先使用）</label>
            <textarea id="customOpening" placeholder="在这里写下你构想的开场剧情……"></textarea>
        </div>

        <div class="gen-wrap">
            <button class="gen-btn" id="genBtn">生 成 设 定</button>
        </div>
    </div>

    <div class="card summary-card">
        <h2 class="section-title">总结区</h2>
        <div class="summary-inner" id="summaryBox">
            <span style="color:#b0a9c2;font-style:italic;">点击上方【生成设定】按钮，玩家设定与所选开场白将自动汇总到这里。</span>
        </div>
    </div>

    <div class="copy-wrap">
        <button class="copy-btn" id="copyBtn">一 键 复 制</button>
    </div>
</div>

<script>
    const OPENINGS = [{"tag": "官方开局 · 核心第一幕", "cls": "daily", "text": "昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。”"}, {"tag": "走向 · 温柔诱哄", "cls": "", "text": "昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。……针对这一情况，你决定【温柔诱哄】：轻抚后颈坦白冲动，引她更进一步。"}, {"tag": "走向 · 借机教导", "cls": "", "text": "昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。……针对这一情况，你决定【借机教导】：扶住纤腰假借兄长身份惩罚。"}, {"tag": "走向 · 顺势反制", "cls": "", "text": "昏黄铜灯下，悠月轻盈地依偎跨坐在我的膝前。纯白校服衬衫紧绷，锁骨白皙一览无遗。她将发热的额头靠在我下颌边轻声呢喃：“哥哥……你还没回答悠月呢。口袋里到底装了什么呀？要是答不上来，今晚悠月可不让你走哦。……针对这一情况，你决定【顺势反制】：环住细腰不再退让，将主动权强势握在手中。"}];
    let selectedIndex = 0;
    const listEl = document.getElementById(''openingList'');
    OPENINGS.forEach(function (op, i) {
        const card = document.createElement(''div'');
        card.className = ''opening-card'' + (i === 0 ? '' selected'' : '''');
        card.dataset.index = i;
        card.innerHTML = ''<span class="idx">'' + (i + 1) + ''</span>'' +
                         ''<span class="tag '' + op.cls + ''">'' + op.tag + ''</span><br>'' +
                         op.text;
        card.addEventListener(''click'', function () {
            document.querySelectorAll(''.opening-card'').forEach(function (c) {
                c.classList.remove(''selected'');
            });
            card.classList.add(''selected'');
            selectedIndex = i;
        });
        listEl.appendChild(card);
    });

    const summaryBox = document.getElementById(''summaryBox'');
    const copyBtn = document.getElementById(''copyBtn'');
    let lastSummaryText = '''';

    function val(id) {
        const v = document.getElementById(id).value.trim();
        return v ? v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom ? custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom ? ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(function() {
                copyBtn.textContent = ''已 复 制 ✓'';
                setTimeout(function() { copyBtn.textContent = ''一 键 复 制''; }, 1800);
            });
        }
    });
</script>
</body>
</html>', '都市') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('spa', '私密水汇 · VIP专属深情护理', '现代都市 · 私密', '🌿', '私密水汇 · VIP专属深情护理', '', '🌿', 'amber', 'from-amber-600 to-orange-600', '{}', '[{"name": "温雅", "tag": "VIP金牌理疗师 (24岁)", "roleType": "女主", "color": "amber", "desc": "<strong>外在面具：</strong> 端庄知性的大牌护理师。<br><strong>隐性诱饵：</strong> 独处时手法常不由自主带着温存撩拨。"}]', '[{"title": "📍 独立VIP精油包厢", "desc": "幽暗香薰包厢内，水汽与檀香氤氲。温雅倒出温热精油贴上你的肩背……", "text": "水汇中心VIP豪华包厢。温雅身着浅杏色开叉旗袍，手掌搓热精油按在肩颈处低语：“贵宾……力道还可以吗？如果您觉得哪里需要加钟放松，一定要告诉温雅哦……”"}]', '[{"name": "沉稳享受", "desc": "放松合眼任由理疗师细致伺候"}, {"name": "调侃坏笑", "desc": "言语试探技师的职业底线"}]', '{"location": "VIP私密水疗包厢·深夜23:15。柔和地灯与精油薄雾。", "story": "温雅跪坐在侧后方，柔嫩手掌裹着温热依兰精油推拿肩颈，开叉旗袍裙摆微缩，温热大腿不经意蹭过你的臂膀：“贵宾……是今天太累了……还是因为温雅按得让您觉得害羞呢？”", "memory": ["水汇VIP体验：温雅进行深度精油肩颈护理"], "status": {"clothes": "温雅：浅杏色开叉旗袍、长发挽起", "posture": "俯身跪坐床侧、双手覆在后背推拿", "stats": "心跳: 110bpm | 羞耻度: 60% | 默契度: 88%", "risk": "走廊偶尔有服务生走过"}, "branches": [{"tag": "A", "title": "反握柔荑", "desc": "反手扣住滑腻手掌低声发问"}, {"tag": "B", "title": "翻身相对", "desc": "翻过身正对视线让她继续"}]}', '2026-09-12 02:01:42', '2026-09-12 02:01:42', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>私密水汇 · VIP专属深情护理</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
