/* 现实修改器专属 6 级折叠面板样式 (1:1 对齐用户截图) */
.reality-panels-container {
  border: 1px solid #383b46 !important;
  border-radius: 8px !important;
  background: #1e2026 !important;
  overflow: hidden !important;
  margin-top: 14px !important;
}
.reality-panel {
  border-bottom: 1px solid #2d303a !important;
}
.reality-panel:last-child {
  border-bottom: none !important;
}
.reality-summary {
  padding: 8px 14px !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  color: #e2e8f0 !important;
  cursor: pointer !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  user-select: none !important;
  background: #202228 !important;
  transition: background 0.15s ease, color 0.15s ease !important;
}
.reality-summary:hover {
  background: #282a32 !important;
  color: #fff !important;
}
.reality-panel[open] > .reality-summary {
  background: #22252e !important;
  color: #38bdf8 !important;
}
.reality-panel[open] > .reality-summary .arrow-indicator {
  color: #38bdf8 !important;
}
.reality-body {
  padding: 12px 16px !important;
  font-size: 12px !important;
  color: #cbd5e1 !important;
  line-height: 1.85 !important;
  background: #181a20 !important;
  border-top: 1px solid #282a32 !important;
}
