INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('deck_horror_ladder', '回魂梯 · 西林街44号', '中式恐怖 · 客观现实锁', '🚪', '回 魂 梯', '西林街44号 · 暴雨夜的第4.5层', '🚪', 'from-stone-700 to-amber-900', 'from-stone-800 to-amber-950', '{"audience": ["喜爱纯正中式民俗微恐、新怪谈、规则怪谈与高智商心理博弈的玩家", "受够了‘玩家说没有鬼AI就跟着说没有鬼’的降智扮演，渴望真正‘客观法则无法被强行篡改’的极致压迫感", "喜欢沉浸式文字冒险与解谜求生风格的玩家"], "tips": ["【客观现实锁】：这里的一切异常都有其不可逆转的物理存在，凭空否认只会加速死兆降临", "【数清台阶】：每一折楼梯正常只有12阶，如果你数出了第13阶，绝对不要踩上去", "【别回头看门缝】：如果身侧紧闭的木门内传出你熟悉亲人的呼唤声，那绝对不是真人"], "quote": "「你以为只要闭上眼睛念三遍‘世界上没有鬼’，踏在脖颈上的冰冷呼吸就会消失吗？」", "originHtml": "\n        <div class=\"space-y-3 font-mono text-xs\">\n          <div class=\"p-4 rounded-xl bg-[#1b221d] border border-emerald-800/40 text-emerald-200 space-y-2\">\n            <div class=\"font-bold text-sm text-emerald-300 flex items-center gap-2\">\n              <span>🚪</span><span>档案编号 · 西林街44号筒子楼失踪案</span>\n            </div>\n            <p class=\"text-gray-300 text-xs leading-relaxed\">\n              始建于1978年的老式红砖筒子楼，绿油漆剥落的水泥墙面上刻满了岁月与污垢。自1996年起，该楼步梯间屡次发生‘踏空坠楼’与‘原地消失’事件。据幸存勘查人员记录，在午夜0点至3点之间，步梯会在4层与5层之间分裂出一道‘永无止境的死循环回廊’。\n            </p>\n          </div>\n        </div>\n        ", "charactersHtml": "\n        <div class=\"space-y-4\">\n          <!-- 恐怖怪谈专属立绘卡片 -->\n          <div class=\"p-4 rounded-xl bg-[#18211b] border border-emerald-900/60 shadow-xl flex flex-col md:flex-row gap-4 items-center md:items-start\">\n            <div class=\"relative w-44 h-64 shrink-0 rounded-xl overflow-hidden border border-emerald-700/40 shadow-inner group cursor-pointer bg-black/60\">\n              <img src=\"/assets/characters/horror_entity_standing.jpg\" alt=\"红绣鞋女子立绘\" class=\"w-full h-full object-cover object-top group-hover:scale-105 transition duration-300\" onclick=\"showFullStandingModal(''/assets/characters/horror_entity_standing.jpg'', ''西林街44号 · 梯间红绣鞋执念灵'')\">\n              <div class=\"absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent p-2 text-center\">\n                <span class=\"text-[10px] text-emerald-300 font-mono\">🔍 点击查看诡异高清单人像</span>\n              </div>\n            </div>\n            <div class=\"flex-1 space-y-2 text-xs\">\n              <div class=\"flex items-center justify-between\">\n                <h4 class=\"font-bold text-sm text-emerald-300 flex items-center gap-1.5\">\n                  <span>👣</span>\n                  <span>红绣鞋执念灵 (西林街44号)</span>\n                </h4>\n                <span class=\"px-2 py-0.5 rounded-full bg-red-950/80 text-red-300 text-[10px] border border-red-700/50 font-mono\">法则实体 · 极度危险</span>\n              </div>\n              <div class=\"text-gray-300 leading-relaxed space-y-1.5 text-[11px]\">\n                <div>• <strong class=\"text-emerald-200\">形态观察：</strong>墨青色褪色旧旗袍、凌乱长发披垂、双手交叠于腹前、脚踏刺目鲜红绣花鞋。</div>\n                <div>• <strong class=\"text-emerald-200\">异常规律：</strong>每当你向下走完一层，墙上的楼层标号依然是‘4F’；空气中的生肉腥味加重一倍。</div>\n                <div>• <strong class=\"text-emerald-200\">生存法则：</strong>不要与她目光直接对视超过五秒；不要试图向她解释‘唯物主义’；用尽一切线索寻找真正的出口生门。</div>\n              </div>\n            </div>\n          </div>\n        </div>\n        "}', '[{"name": "西林街44号梯间执念灵 (红绣鞋女子)", "tag": "客观现实锁 · 步梯空间异变源", "roleType": "异象实体", "avatar": "/assets/characters/horror_entity_standing.jpg", "standing_image": "/assets/characters/horror_entity_standing.jpg", "costumes": [{"name": "旧式旗袍 · 猩红绣花鞋", "url": "/assets/characters/horror_entity_standing.jpg", "desc": "泛灰褪色的墨青色老布旗袍，脚下一双刺目的鲜红丝绒绣花鞋，悄无声息踏在水泥阶梯上"}], "appearance": "长发如墨披散掩面，露出一双漆黑无瞳仁的湿冷眼眸，苍白没有血色的长指自然垂落，身后是一闪一闪的昏黄钨丝灯", "personality": "不怒不悲，遵循着死后四十余年固定不改的‘守阶之约’。她不会顺从你的否定，只会以冰冷的客观事实粉碎所有侥幸", "desc": "西林街44号老式筒子楼4.5层步梯的守护者。你越是试图在脑海中说服自己‘这里没有鬼’，四周的空气便越发粘稠刺鼻。她正踩在向上延伸的第十三级台阶上，低头居高临下地注视着你……"}, {"name": "迷失者 (玩家视角)", "tag": "困局中的探索者", "roleType": "玩家", "avatar": "https://api.dicebear.com/7.x/bottts/svg?seed=LadderLostMan", "desc": "深夜误入西林街44号筒子楼的普通人，手机完全失去网络信号，被困在永远走不完的第4层与第5层之间。"}]', '[{"title": "西林街44号 · 暴雨夜的虚构半层", "desc": "破旧的水泥步梯，声控灯只亮昏黄暗红的光芒。脚下踩着黏腻的水渍，转角杂物堆上的红绣花鞋正对你的脚尖。"}]', '["中式民俗", "规则怪谈", "生理惊悚"]', '{"location": "西林街44号楼 · 三楼转四楼拐角平台 · 深夜 23:42", "story": "脚下的球鞋踩在油腻潮湿的水泥阶梯上，发出沉闷的黏滞声。\n\n你刚从加完班的末班公交车下来，楼道里的声控灯早就坏了，只有你手机屏幕泛出的微弱亮光，在斑驳剥落的绿油漆墙面上投出一小圈惨白的虚影。\n\n你顺着楼梯向上数着：一层、两层、三层……\n\n然而，当你迈上本该是四楼的转角平台时，脚步硬生生僵在了半空。\n\n楼层标牌上并没有写着熟悉的阿拉伯数字“4”，而是在原本泛黄的石灰墙面上，用某种暗红发黑、半干不干的油性颜料，歪歪扭扭地手写着一个刺眼的数字：\n\n【 4 . 5 】\n\n空气里突然弥漫开一股极浓烈的生肉腥味，混杂着受潮纸钱燃烧后的余温。转角处堆放着半人高的腐朽旧纸箱，纸箱顶部，摆着一只不知道属于谁的红色塑料绣花拖鞋，鞋尖正直勾勾地对准了你站立的方向。\n\n头顶上方的楼梯间，传来极其缓慢、沉重、湿漉漉的拖拽声。\n啪嗒……沙沙……\n每响一声，电表箱的红光就诡异地微闪一下。而在你身后的下楼通道，原本你刚刚走上来的楼梯不知何时已经没入了浓稠得化不开的黑雾，连一丝暴雨声都透不过来。", "memory": ["入住西林街44号楼第一天，中介曾叮嘱“晚上回家千万不要数台阶，若看到半层数字绝对不能出声”", "客观现实锁已生效：身后退路已没入深渊，空间已被规则封死"], "status": {"clothes": "湿透的通勤西装 / 握着手机的冰凉指尖", "posture": "僵在半层拐角台阶上，后背紧贴冰凉潮湿的墙壁", "stats": "心跳: 138bpm (急剧狂飙) / SAN值: 82", "risk": "极高 (上方湿漉拖拽物正向平台接近)"}, "branches": [{"tag": "A", "title": "贴墙屏息，按灭手机", "desc": "迅速熄灭手机光源，屏住呼吸贴紧墙角阴影，静候上方脚步的动向"}, {"tag": "B", "title": "翻查杂物纸箱找线索", "desc": "强忍腥味快速翻动身侧的烂纸箱，寻找能克制邪祟的黄铜物件或门禁卡"}, {"tag": "C", "title": "叩响4.5层生锈防盗门", "desc": "拐角平台竟嵌着一扇无门牌号的生锈铁门，鼓起勇气叩击三声求救"}, {"tag": "D", "title": "咬牙跨步猛冲上五楼", "desc": "无视诡异现象，闭紧双眼握紧双拳，发足狂奔试图冲破这半层回廊"}]}', '2026-09-13 08:46:54', '2026-09-13 09:31:17', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>回魂梯 · 西林街44号</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">中式恐怖 · 客观现实锁</span>
        <h1>回魂梯 · 西林街44号</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            脚下的球鞋踩在油腻潮湿的水泥阶梯上，发出沉闷的黏滞声。

你刚从加完班的末班公交车下来，楼道里的声控灯早就坏了，只有你手机屏幕泛出的微弱亮光，在斑驳剥落的绿油漆墙面上投出一小圈惨白的虚影。

你顺着楼梯向上数着：一层、两层、三层……

然而，当你迈上本该是四楼的转角平台时，脚步硬生生僵在了半空。

楼层标牌上并没有写着熟悉的阿拉伯数字“4”，而是在原本泛黄的……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
            <div class="p-item">
                <h4><span class="dot"></span>西林街44号梯间执念灵 (红绣鞋女子) · 登场人物</h4>
                <p>西林街44号老式筒子楼4.5层步梯的守护者。你越是试图在脑海中说服自己‘这里没有鬼’，四周的空气便越发粘稠刺鼻。她正踩在向上延伸的第十三级台阶上，低头居高临下地注视着你……</p>
            </div>
            
            <div class="p-item">
