}

.wrap{max-width:52em;margin:0 auto;}

/* ---------- 标题 ---------- */
.hero{
  text-align:center;
  padding:2.2em 1em 1.8em;
  background:linear-gradient(135deg,rgba(255,255,255,.9),rgba(255,240,245,.75));
  border-radius:1.4em;
  box-shadow:0 0.6em 2em rgba(209,96,129,.16);
