  margin-bottom:.35em;
  text-shadow:0 .08em .12em rgba(209,96,129,.18);
}
.hero p{
  font-size:.95em;
  color:#a87789;
  letter-spacing:.12em;
}
.hero .sub{
  display:inline-block;
