  transition:transform .25s ease,box-shadow .25s ease;
}
.char:hover{
  transform:translateY(-.2em);
  box-shadow:0 .6em 1.6em rgba(209,96,129,.18);
}
.char-head{
  display:flex;align-items:center;gap:.8em;
  margin-bottom:.7em;flex-wrap:wrap;
}
.char-name{
  font-size:1.15em;font-weight:700;color:#d16081;
  letter-spacing:.04em;
}
.char-tag{
  font-size:.72em;
