setTimeout(() => { showPanel(''👾 来自 零 的消息'', ''虽然弹窗关了，但你的系统已经被本小姐接管了哦~大叔乖乖去大厅第一个找我吧，噗库库~♡''); }, 500);
}
}
function handleHeaderClick() {
headerClickCount++;
if(headerClickCount >= 4) {
if(isHacked) {
restoreSystem();
} else {
if(!hasBeenHackedOnce) {
document.getElementById(''afOverlay'').style.display = ''flex'';
hasBeenHackedOnce = true;
headerClickCount = 0;
} else {
executeHack(true);
}
}
}
}
function restoreSystem() {
isHacked = false;
headerClickCount = 0;
document.getElementById(''chat-ui-k8j2h4g9'').classList.remove(''hacked-mode'');
document.getElementById(''headerEmoji'').innerText = ''🍑'';
document.getElementById(''headerText'').innerText = ''亚朵包养'';
document.getElementById(''topBalance'').innerText = ''余额: ￥9999999999'';
document.getElementById(''msgTitle'').innerText = ''私密会话 (42)'';
document.getElementById(''profileHead'').innerHTML = originalProfileHead;
document.getElementById(''profileMenuList'').innerHTML = originalProfileMenu;
document.getElementById(''homeFilters'').innerHTML = originalHomeFilters;
const zeroIndex = girlsData.findIndex(g => g.id === 0);
if(zeroIndex !== -1) girlsData.splice(zeroIndex, 1);
renderList();
renderMsgList();
renderOrderList();
showPanel(''系统恢复'', ''系统已恢复正常，感谢您的耐心等待。'');
}
renderList();
