      window.openModal = function(type) {
        var overlay = document.getElementById(''modalOverlay'');
        var title = document.getElementById(''modalTitle'');
        var content = document.getElementById(''modalContent'');
        if (!overlay || !title || !content) {
          console.error(''Modal elements not found'');
          return;
        }
        title.textContent = modalData[type].title;
        content.innerHTML = modalData[type].content;
        setTimeout(function() {
          if (type === ''preview'') {
            window.loadCharacterData();
          }
          if (type === ''custom'') {
            window.loadCustomData();
          }
        }, 0);
        overlay.classList.add(''active'');
      };
      
      window.closeModal = function() {
        var overlay = document.getElementById(''modalOverlay'');
        if (overlay) {
          overlay.classList.remove(''active'');
        }
      };
      
      window.closeWarning = function() {
        var warningOverlay = document.getElementById(''warningOverlay'');
        if (warningOverlay) {
          warningOverlay.classList.remove(''active'');
        }
        
        // 显示音乐初始化弹窗
        var musicInit = document.getElementById(''music-init'');
        if (musicInit) {
          setTimeout(function() {
            musicInit.classList.add(''active'');
          }, 300);
        }
      };
    }
    
    document.addEventListener(''DOMContentLoaded'', initApp);
