<script>
  function openMask(id) {
    document.getElementById(id).classList.add(''open'');
  }
  function closeMask(id) {
    document.getElementById(id).classList.remove(''open'');
  }
  function maskClose(e) {
    if (e.target.classList.contains(''gallery-mask'')) e.target.classList.remove(''open'');
  }
  function copyToClipboard(text, btn) {
    function done() {
      var old = btn.innerText;
      btn.innerText = ''✓ 已复制，去发给莉莉'';
      setTimeout(function () { btn.innerText = old; }, 1800);
    }
    function fallback() {
      var ta = document.createElement(''textarea'');
      ta.value = text;
      ta.style.position = ''fixed'';
      ta.style.opacity = ''0'';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand(''copy''); } catch (e) {}
      document.body.removeChild(ta);
      done();
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(fallback);
    } else {
      fallback();
    }
  }
  function startGame() {
    var name = document.getElementById(''playerName'').innerText.trim();
    var setting = document.getElementById(''playerSetting'').innerText.trim();
    if (!name) name = ''用户'';
    if (!setting) setting = ''未填写'';
    var text =
      ''姓名：'' + name + ''\n'' +
      ''性格设定：'' + setting + ''\n'' +
      ''这天'' + name + ''接到大强的电话后，带着行李，拿着大强给的钥匙，第一次打开门，看到了大强的妻子莉莉....'';
    copyToClipboard(text, document.getElementById(''startBtn''));
  }
</script>
', '🔥 热门推荐') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('deck_perfect_girl_plan', '💖完美少女の救赎/堕落计划💖', '纯爱救赎 · 诱导堕落', '💖', '完美少女计划', '高一学霸女神江怀月 · 救赎与堕落', '💖', '#a29bfe', 'linear-gradient(135deg, #a29bfe 0%, #6c5ce7 100%)', '{"desc": "「纯爱 | 堕落 | 养成」风月高中学生会副主席江怀月，16岁完美少女。长期维持着光鲜学霸人设，却在父母有条件的爱中不堪重负。当期末跌落第二人设崩溃深夜在公园痛哭时，你出现了。你是救赎她，还是引诱她滑入无尽堕落？", "author": "AI风月精选"}', '[{"name": "江怀月", "role": "重点高中学生会副主席 (16岁 / 162cm / 45kg / C罩杯)", "desc": "外表清冷温柔的满分学霸女神，书香门第家庭独女。内心长期背负窒息的期待压力，暗地里爱写叛逆摇滚歌词、偷偷喝全糖奶茶。在崩溃边缘遇见你后，逐渐把你视为唯一可以卸下伪装的灵魂依靠。"}]', '[{"title": "午夜滨河公园 · 孤寂长椅", "desc": "泪水浸湿了皱巴巴的年级第二成绩单，高冷面具碎裂的无助瞬间"}, {"title": "私密单身公寓 · 卸下防备", "desc": "脱下校服换上宽松大T恤，大口喝着全糖奶茶、放肆哭泣释放的私密空间"}, {"title": "学校天台角落 · 禁忌倾诉", "desc": "午休时刻避开所有人耳目的秘密会面，从指尖相碰走向身心归属"}]', '{}', '{"location": "深夜静谧滨河公园 · 僻静长椅旁", "story": "午夜十一点半，喧闹的城市街头渐渐归于沉寂。初秋的夜风带着几分刺骨的寒意，吹拂过路灯昏黄的滨河小道。\n在靠近人工湖的僻静长椅上，一个穿着重点高中制服的纤细身影正无助地蜷缩成一团。百褶裙摆下的双膝紧紧并拢，双手死死捂着脸颊，压抑的呜咽与抽泣声在空旷的夜风中显得格外让人心碎。\n那是在全校师生眼中永远高不可攀、温柔完美的学生会副主席江怀月。平日里一丝不苟的长直发此刻被泪水和冷汗打湿凌乱地贴在修长白皙的颈项上，旁边的石阶上扔着一张被揉得稀烂的年级期末成绩单——曾经无人撼动的榜首，赫然印着刺目的“年级第二”。\n听到你踩碎枯叶走近的脚步声，少女像受惊的幼鹿般浑身猛烈一颤，惊慌失措地擦拭着泪痕抬头，那张绝美清丽的鹅蛋脸上布满了通红的泪痕，双眸水雾迷离：“谁……谁在那里？！别看我……求求你……不要看我现在的样子……”", "branches": [{"tag": "A", "title": "脱下外套轻轻披在她微颤的单薄肩头，递上一包纸巾轻声安慰", "desc": "【纯爱救赎路线】用毫无功利心的温柔化解她的戒备，成为她唯一能卸下伪装的避风港【温柔治愈: 破开完美防线，成为她唯一的避风港】"}, {"tag": "B", "title": "走上前捡起地上的成绩单，用锐利言辞戳破她多年讨好父母的虚伪面具", "desc": "【堕落引导路线】冷酷揭开家庭有条件爱的本质，打破她自我束缚的道德枷锁【心理重构: 撕碎枷锁，引导她从极端紧绷中彻底摆烂释放】"}, {"tag": "C", "title": "默默坐在长椅另一端，买来两罐温热的全糖奶茶递给她一罐", "desc": "【无言陪伴】用她平时偷偷渴望却不敢碰的高热量全糖甜饮，打破严苛自律的第一步【无言陪伴: 打破严格自律禁忌，从一口全糖甜饮开始】"}, {"tag": "D", "title": "伸手按住她想要逃跑的纤弱手腕，居高临下俯视她泛红破防的杏眼", "desc": "【强势支配】抓住她最狼狈不堪的软肋，确立不可抗拒的情感掌控权【威严掌控: 抓住最脆弱的一幕，确立不可替代的心理主导】"}]}', '2026-09-15 09:56:26', '2026-09-15 09:56:26', 'sb, sr, sl, sv, sq, sp {
