  text-overflow: ellipsis; /* 超出显示省略号 */
}

/* 心声 sq - 网格布局 */
sq {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0 18px;
  align-items: start;
  margin-bottom: 6px;
}

/* 心声标签 */
sq::before {
