/* =========================================
   状态栏美化
   ========================================= */
details {
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    padding: 10px;
    margin: 15px 0;
    background: linear-gradient(135deg, rgba(138,43,226,0.05), rgba(75,0,130,0.05));
}

details summary {
    cursor: pointer;
    font-weight: bold;
    padding: 5px;
    transition: color 0.3s;
}

details summary:hover {
    color: #BA55D3;
}

/* 对话颜色 */
font[color="#0000FF"] {
    font-weight: bold;
}

font[color="#800080"] {
    font-weight: bold;
}

/* 移动端适配 */
@media (max-width: 768px) {
    div[class*="-c-"] {
        width: 180px;
        height: 270px;
    }
    
    div[class*="-f-"] {
        width: 180px;
        height: 135px;
    }
    
