.resident-card:hover .img-box img { transform: scale(1.1); opacity: 1; }
.card-body { padding: 15px; }
.card-body h3 { font-size: 18px; color: var(--primary); margin-bottom: 5px; display: flex; justify-content: space-between; align-items: center; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: #0f0; display: inline-block; box-shadow: 0 0 5px #0f0; }
.card-tags { margin-bottom: 10px; }
.tag { font-size: 10px; padding: 2px 6px; border-radius: 4px; margin-right: 5px; border: 1px solid var(--accent); color: var(--primary); background: rgba(233,69,96,0.1); }
.card-desc { font-size: 13px; color: var(--gray); height: 60px; overflow: hidden; margin-bottom: 15px; line-height: 1.4; }
.action-btn { width: 100%; padding: 10px; border: none; border-radius: 6px; background: linear-gradient(to right, var(--secondary), var(--accent)); color: white; font-weight: bold; cursor: pointer; transition: 0.3s; }
.action-btn:hover { letter-spacing: 1px; filter: brightness(1.2); }
.custom-layout { display: flex; flex-wrap: wrap; gap: 20px; }
.author-side { flex: 1; min-width: 250px; background: rgba(149, 7, 64, 0.1); border-left: 4px solid var(--accent); padding: 20px; border-radius: 4px; height: fit-content; }
.author-side h4 { color: var(--gold); margin-bottom: 10px; }
.author-side p { font-size: 13px; color: #bbb; margin-bottom: 10px; }
.form-main { flex: 3; min-width: 300px; }
.section-box { background: var(--card-bg); padding: 20px; border-radius: 12px; margin-bottom: 20px; border: 1px solid rgba(255,255,255,0.05); }
.section-title { font-size: 16px; color: var(--primary); margin-bottom: 15px; border-bottom: 1px solid rgba(233, 69, 96, 0.3); padding-bottom: 5px; }
.form-group { margin-bottom: 15px; }
.form-group label { display: block; font-size: 12px; color: var(--gold); margin-bottom: 5px; }
.form-input { width: 100%; background: #0f3460; border: 1px solid rgba(255,255,255,0.1); padding: 10px; color: white; border-radius: 6px; }
.form-input:focus { border-color: var(--primary); }
.kink-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); gap: 10px; }
.kink-item { background: #1a1a2e; border: 1px solid #333; padding: 8px; border-radius: 6px; text-align: center; font-size: 12px; cursor: pointer; transition: 0.3s; }
.kink-item.active { border-color: var(--primary); background: rgba(233, 69, 96, 0.2); color: var(--primary); }
.npc-list-item { background: #0f3460; padding: 10px; border-radius: 8px; margin-bottom: 10px; position: relative; border: 1px solid transparent; cursor: pointer; }
.npc-list-item.selected { border-color: var(--gold); background: rgba(212, 175, 55, 0.1); }
.npc-list-item h5 { color: var(--primary); font-size: 14px; }
.npc-list-item p { font-size: 11px; color: var(--gray); }
.preview-box { background: #000; padding: 15px; border-radius: 8px; font-family: monospace; font-size: 12px; color: #0f0; max-height: 200px; overflow-y: auto; white-space: pre-wrap; margin-top: 15px; border: 1px solid #333; }
.copy-btn { width: 100%; padding: 15px; background: var(--primary); color: white; border: none; border-radius: 30px; font-weight: bold; font-size: 16px; cursor: pointer; margin-top: 20px; box-shadow: 0 5px 15px rgba(233, 69, 96, 0.4); }
.modal { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); display: none; justify-content: center; align-items: center; z-index: 2000; }
.modal-content { background: var(--card-bg); padding: 25px; border-radius: 12px; width: 90%; max-width: 400px; border: 1px solid var(--primary); }
.toast { position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%); background: var(--primary); color: white; padding: 10px 30px; border-radius: 20px; display: none; z-index: 3000; box-shadow: 0 0 20px rgba(233,69,96,0.5); }
footer { text-align: center; padding: 20px; font-size: 11px; color: #555; }
footer a { color: #666; text-decoration: none; }
@media (max-width: 768px) { .author-side { order: 2; } .form-main { order: 1; } }
</style>
</head>
