</div>
<!-- 预览 -->
<div class="section-box">
<div class="section-title">📋 信息预览</div>
<div class="preview-box" id="finalPreview">等待生成内容...</div>
<button class="copy-btn" id="copyBtn" onclick="copyConfig()">📑 复制完整系统设定</button>
</div>
</div>
</div>
</div>
<!-- 自定义NPC弹窗 -->
<div class="modal" id="npcModal">
<div class="modal-content">
<h3 style="color:var(--primary); margin-bottom:15px;">添加新NPC</h3>
<div class="form-group"><label>姓名</label><input type="text" id="new_name" class="form-input"></div>
<div class="form-group"><label>年龄</label><input type="text" id="new_age" class="form-input"></div>
<div class="form-group"><label>性格</label><input type="text" id="new_personality" class="form-input"></div>
<div class="form-group"><label>身份</label><input type="text" id="new_identity" class="form-input"></div>
<div class="form-group"><label>背景</label><textarea id="new_bg" class="form-input"></textarea></div>
<button class="action-btn" onclick="addNewNpc()">➕ 确认添加</button>
<button class="action-btn" style="background:#444; margin-top:10px;" onclick="closeModal()">取消</button>
</div>
</div>
<div class="toast" id="toast">已成功复制到剪贴板</div>
<footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank">本页面采用AI风月-创作大师生成</a></footer>
<script>
function switchTab(tabId) {
    document.querySelectorAll(''.content-area'').forEach(el => el.classList.remove(''active''));
    document.querySelectorAll(''.tab-btn'').forEach(el => el.classList.remove(''active''));
    document.getElementById(tabId).classList.add(''active'');
    event.currentTarget.classList.add(''active'');
    window.scrollTo(0,0);
}
function toggleKink(el) { el.classList.toggle(''active''); updatePreview(); }
function selectNpc(el) { el.classList.toggle(''selected''); updatePreview(); }
function showNpcModal() { document.getElementById(''npcModal'').style.display = ''flex''; }
function closeModal() { document.getElementById(''npcModal'').style.display = ''none''; }
function addNewNpc() {
    const name = document.getElementById(''new_name'').value;
    const age = document.getElementById(''new_age'').value;
    const pers = document.getElementById(''new_personality'').value;
    const iden = document.getElementById(''new_identity'').value;
    const bg = document.getElementById(''new_bg'').value;
    if(!name) return;
    const div = document.createElement(''div'');
    div.className = ''npc-list-item selected'';
    div.onclick = function() { this.classList.toggle(''selected''); updatePreview(); };
    div.innerHTML = `<h5>👤 ${name}</h5><p>${age} | ${pers} | ${iden}</p><div style="display:none">${bg}</div>`;
    document.getElementById(''npcList'').appendChild(div);
    closeModal();
    updatePreview();
}
function updatePreview() {
    const pName = document.getElementById(''p_name'').value || ''龙傲天'';
    const pGender = document.getElementById(''p_gender'').value || ''男'';
    const pPers = document.getElementById(''p_personality'').value || ''温柔体贴'';
    const pIden = document.getElementById(''p_identity'').value || ''高中生'';
    const pOther = document.getElementById(''p_other'').value || ''无'';
    const kinks = Array.from(document.querySelectorAll(''.kink-item.active'')).map(el => el.innerText).join('', '') || ''无'';
    let npcInfo = '''';
    document.querySelectorAll(''.npc-list-item.selected'').forEach(el => {
        const h5 = el.querySelector(''h5'').innerText;
        const p = el.querySelector(''p'').innerText;
        const bg = el.querySelector(''div'').innerText;
        npcInfo += `【NPC：${h5}】\n详情：${p}\n背景：${bg}\n\n`;
    });
    const intro = document.getElementById(''custom_intro'').value || ''默认开场'';
    const fullText = `【玩家信息】\n姓名：${pName}\n性别：${pGender}\n性格：${pPers}\n身份：${pIden}\n核心性癖：${kinks}\n其他：${pOther}\n\n【NPC信息】\n${npcInfo}【剧情开场】\n${intro}\n\n(请按照Aphrodite👦管理员模拟系统规则开始游戏)`;
    document.getElementById(''finalPreview'').innerText = fullText;
}
function quickCopy(name, traits) {
    const admin = document.getElementById(''shop_admin_name'').value || ''新任管理员'';
    const iden = document.getElementById(''shop_admin_identity'').value || ''管理员'';
    const text = `【管理员查房确认】\n\n👤 管理员设定：\n姓名：${admin}\n身份：${iden}\n\n📦 目标住户：\n姓名：${name}\n核心属性：${traits}\n\n(【👦】请按照月桂庄公寓规则开始剧情)`;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function copyConfig() {
    updatePreview();
    const text = document.getElementById(''finalPreview'').innerText;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function showToast() {
    const t = document.getElementById(''toast'');
    t.style.display = ''block'';
    setTimeout(() => t.style.display = ''none'', 2000);
}
document.querySelectorAll(''input, textarea'').forEach(el => el.addEventListener(''input'', updatePreview));
updatePreview();
</script>
</body>
</html>', '都市') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, created_at, updated_at, custom_css, custom_html, category) VALUES ('deck_nude_girls_school', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', '🌸', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', 'https://catai.wiki/4d39b21c-82c1-4986-8feb-1f5a25806e00/cover', 'bg-pink-950/90 text-pink-300 border-pink-600/60', 'from-rose-600 to-purple-600', '{"title": "🌸全裸女校，只有你是特招", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "bg_image": "https://catai.wiki/6ef5e821-d7db-4a16-808a-a90d95975900/bg"}', '[{"name": "主人公", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "role_type": "protagonist"}]', '[{"title": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "story": "“新生同学，欢迎来到圣伊甸。在这里，身体是唯一的诚实礼仪。”校门旁的更衣室门推开，成熟丰满、一丝不挂的女校长塞西莉亚优雅地端着茶杯注视着你。在她的注视下，你脱下了身上的最后一件衣物。当踏入恒温26℃的林荫校园，走廊与草坪上成百上千名赤身裸体的贵族少女们齐刷刷转过头来，目光聚焦在全校唯一一具男性肉体上，窃窃私语与好奇惊呼此起彼伏……", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察周遭人物的微表情与防备程度，稳步建立信任关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "抓住对方好奇或破防的瞬间，采取大胆主动的行动颠覆攻守局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将关键人物引向更隐秘的角落或私密房间，拉开二人深度交互帷幕"}, {"tag": "D", "title": "直接挑明自身特殊需求与条件", "desc": "打破常规客套，直言不讳地提出极具侵略性与掌控欲的契约规则"}]}]', '2026-09-15 15:03:14', '2026-09-15 15:03:14', '/* ========== 全局 ========== */
body,
p,
span,
div,
details,
summary,
td,
th,
li,
blockquote {
    font-size: 16px !important;
    font-family: ''Microsoft YaHei'', ''PingFang SC'', sans-serif !important;
}

/* ===== 对话颜色 ===== */
.player-talk {
    color: #1a73e8 !important;
    font-weight: 500;
}
.npc-talk {
    color: #d63384 !important;
    font-weight: 500;
}

/* ===== 容器基准 ===== */
.w {
    display: block;
    font-family: system-ui, -apple-system, sans-serif;
    font-size: 14px;
    color: #4a2c40;
    line-height: 1.5;
    background: linear-gradient(135deg, #fff0f5 0%, #fef5f9 100%);
    padding: 8px;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(255, 126, 179, 0.1);
}

/* ===== 状态面板 (a) ===== */
.w .a {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .a[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 师生图鉴 (b) ===== */
.w .b {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
}

/* ===== 记忆区 (star-memory) ===== */
.w .star-memory {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .star-memory[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 隐藏原生三角 ===== */
.w .a summary::-webkit-details-marker,
.w .b summary::-webkit-details-marker,
.w .star-memory summary::-webkit-details-marker,
.w .m summary::-webkit-details-marker {
    display: none;
}
.w .a summary,
.w .b summary,
.w .star-memory summary,
.w .m summary {
    list-style: none;
}

/* ===== 标题通用 ===== */
.w .a summary,
.w .b summary,
.w .star-memory summary {
    cursor: pointer;
    padding: 10px 12px;
    font-weight: 600;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.25s ease;
    background: linear-gradient(90deg, rgba(255, 126, 179, 0.13) 0%, rgba(255, 255, 255, 0) 100%);
    color: #d81b60;
    font-size: 15px;
    border-bottom: 1px solid transparent;
}
.w .a[open]>summary,
.w .b[open]>summary,
.w .star-memory[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.2);
}

/* ===== 箭头动画 ===== */
.w .a summary::after,
.w .b summary::after,
.w .star-memory summary::after {
    content: "▼";
    font-size: 11px;
    color: #ff758c;
    opacity: 0.7;
    transition: transform 0.3s ease;
    margin-left: 8px;
}
.w .a[open]>summary::after,
.w .b[open]>summary::after,
.w .star-memory[open]>summary::after {
    transform: rotate(180deg);
}

/* ===== Hover ===== */
.w .a summary:hover,
.w .b summary:hover,
.w .star-memory summary:hover {
    background: rgba(255, 126, 179, 0.18);
}

/* ===== 展开动画 ===== */
.w .a[open]>*:not(summary),
.w .b[open]>*:not(summary),
.w .star-memory[open]>*:not(summary) {
    animation: panel-fade-in 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes panel-fade-in {
    0% {
        opacity: 0;
        transform: translateY(-4px);
    }
    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ===== 状态条目容器 ===== */
.w .r {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    margin: 5px 10px;
    background: rgba(255, 255, 255, 0.85);
    border-radius: 6px;
    padding: 4px 0;
    border: 1px solid rgba(255, 126, 179, 0.12);
    transition: background 0.2s ease;
}
.w .r:hover {
    background: rgba(255, 255, 255, 0.96);
}

/* ===== 粉色标签 ===== */
.w .k {
    display: inline-block;
    background: linear-gradient(135deg, #ff7eb3 0%, #ff758c 100%);
    color: white;
    padding: 2px 10px;
    font-size: 12px;
    font-weight: 600;
    border-radius: 4px;
    margin: 0 10px 2px 10px;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
    white-space: nowrap;
}

/* ===== 内容值 ===== */
.w .v {
    display: block;
    padding: 2px 10px 4px 10px;
    font-size: 13px;
    color: #4a2c40;
    width: 100%;
    box-sizing: border-box;
    line-height: 1.6;
    word-wrap: break-word;
    white-space: normal;
}

/* ===== 师生图鉴内部卡片 (m) ===== */
.w .m {
    background: rgba(255, 240, 245, 0.6);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ff758c;
}
.w .m summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
}
.w .mi {
    padding: 6px 10px;
    margin: 4px 6px 8px 6px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    font-size: 13px;
    color: #553a4b;
    line-height: 1.6;
}

/* ===== 记忆区内层 details ===== */
.w .star-memory details {
    background: rgba(255, 245, 248, 0.5);
    border-radius: 6px;
    margin: 6px 10px;
    border-left: 3px solid #ffa5b9;
    overflow: hidden;
}
.w .star-memory details summary {
    padding: 8px 10px;
    font-size: 13px;
    color: #6a4a5b;
    background: transparent;
    font-weight: 500;
    cursor: pointer;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.2s ease;
    border-bottom: 1px solid transparent;
}
.w .star-memory details summary:hover {
    background: rgba(255, 126, 179, 0.10);
}
.w .star-memory details[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.15);
}
.w .star-memory details summary::-webkit-details-marker {
    display: none;
}
.w .star-memory details summary::after {
    content: "▸";
    font-size: 12px;
    color: #ff758c;
    opacity: 0.6;
    transition: transform 0.25s ease;
    margin-left: 8px;
}
.w .star-memory details[open]>summary::after {
    transform: rotate(90deg);
}

/* ===== 记忆区表格容器 ===== */
.w .star-memory details .table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    margin: 6px 8px 8px 8px;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.6);
    padding: 4px 0;
}

/* ===== 记忆区表格（HTML表格） ===== */
.w .star-memory table {
    width: 100%;
    min-width: 340px;
    border-collapse: collapse;
    font-size: 13px;
    color: #4a2c40;
    table-layout: fixed;
}
.w .star-memory table th,
.w .star-memory table td {
    padding: 6px 4px;
    text-align: left;
    vertical-align: top;
    border-bottom: 1px solid rgba(255, 126, 179, 0.10);
    word-wrap: break-word;
    overflow-wrap: break-word;
    line-height: 1.5;
}
.w .star-memory table th {
    background: rgba(255, 126, 179, 0.08);
    font-weight: 600;
    font-size: 12px;
    color: #b34a6a;
    letter-spacing: 0.3px;
    border-bottom: 2px solid rgba(255, 126, 179, 0.20);
}
/* ===== 列宽分配：编号窄，时间窄，场景窄，内容宽 ===== */
.w .star-memory table th:nth-child(1),
.w .star-memory table td:nth-child(1) {
    width: 10%;
    min-width: 40px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(2),
.w .star-memory table td:nth-child(2) {
    width: 18%;
    min-width: 70px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(3),
.w .star-memory table td:nth-child(3) {
    width: 18%;
    min-width: 60px;
    padding-right: 2px;
}
.w .star-memory table th:nth-child(4),
.w .star-memory table td:nth-child(4) {
    width: 54%;
    min-width: 120px;
}
/* ===== 表格行 hover ===== */
.w .star-memory table tr:hover td {
    background: rgba(255, 126, 179, 0.04);
}
/* ===== 表格最后一行无边框 ===== */
.w .star-memory table tr:last-child td {
    border-bottom: none;
}

/* ===== 记忆区文本表格（备选：纯文本表格美化） ===== */
.w .star-memory details .text-table {
    display: block;
    margin: 6px 8px 8px 8px;
    padding: 8px 10px;
    background: rgba(255, 255, 255, 0.6);
    border-radius: 6px;
    font-size: 13px;
    line-height: 1.7;
    color: #4a2c40;
    white-space: pre-wrap;
    word-break: break-word;
    overflow-x: auto;
    font-family: ''SF Mono'', ''Menlo'', ''Monaco'', ''Consolas'', ''Liberation Mono'', monospace;
}
/* ===== 文本表格中的行（模拟） ===== */
.w .star-memory details .text-table .row {
    display: block;
    padding: 2px 0;
    border-bottom: 1px solid rgba(255, 126, 179, 0.06);
}
.w .star-memory details .text-table .row:last-child {
    border-bottom: none;
}
/* ===== 文本表格中的列（用 inline-block 模拟，编号/时间/场景窄，内容宽） ===== */
.w .star-memory details .text-table .col-id {
    display: inline-block;
    min-width: 36px;
    font-weight: 600;
    color: #b34a6a;
}
.w .star-memory details .text-table .col-time {
    display: inline-block;
    min-width: 72px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-scene {
    display: inline-block;
    min-width: 64px;
    color: #6a4a5b;
}
.w .star-memory details .text-table .col-content {
    display: inline;
    color: #4a2c40;
}

/* ===== 记忆区说明文字 (.i) ===== */
.w .star-memory .i {
    display: block;
    margin: 4px 10px 10px 10px;
    font-size: 12px;
    color: #a08496;
    opacity: 0.8;
    font-style: normal;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    border-left: 2px solid rgba(255, 126, 179, 0.3);
}

/* ===== 其他辅助 ===== */
.w .t {
    display: block;
    font-weight: bold;
    font-size: 14px;
    color: #d81b60;
    margin: 12px 10px 4px 10px;
    padding-left: 8px;
    border-left: 3px solid #ff758c;
}
.w .q {
    display: block;
