/* XJX_MEMORY_START */
.fy-memory{width:100%;max-width:480px;box-sizing:border-box;margin:12px 0 6px;padding:12px 14px 13px;border:1px solid rgba(170,182,189,.42);border-radius:15px;background:linear-gradient(145deg,rgba(255,255,255,.97),rgba(255,250,251,.94));box-shadow:0 10px 28px rgba(93,70,82,.10),inset 0 1px rgba(255,255,255,.9);color:#463d43;font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif;font-size:12px;line-height:1.6}
.fy-memory,.fy-memory *{box-sizing:border-box}
.fy-memory>summary{display:flex;align-items:center;gap:8px;margin:0 0 8px;padding:0;border:0;list-style:none;cursor:pointer;user-select:none;font-weight:700;font-size:13px;line-height:1.2;color:#5e5058;letter-spacing:.05em}
.fy-memory>summary::-webkit-details-marker{display:none}
.fy-memory>summary::after{content:"点击折叠";margin-left:auto;font-size:10.5px;font-weight:600;color:#a9a2a8}
.fy-memory:not([open])>summary::after{content:"点击展开"}
.fy-mem-section{margin:8px 0;border:1px solid rgba(130,108,119,.12);border-radius:9px;background:rgba(255,255,255,.62);overflow:hidden}
.fy-mem-h{display:flex;align-items:center;gap:6px;padding:7px 10px;font-weight:700;font-size:12px;line-height:1.3;color:#5e5058}
.fy-mem-count{display:inline-block;padding:1px 7px;border-radius:999px;background:rgba(170,182,189,.18);color:#7a8a93;font-size:10.5px;font-weight:700}
.fy-mem-table{width:100%;border-collapse:collapse;font-size:11.5px;line-height:1.5}
.fy-mem-table th{padding:5px 6px;background:rgba(170,182,189,.14);color:#5e5058;font-weight:700;text-align:left;border:1px solid rgba(130,108,119,.14);white-space:nowrap}
.fy-mem-table td{padding:5px 6px;border:1px solid rgba(130,108,119,.12);vertical-align:top;color:#5e5058}
.fy-mem-cycle{margin:8px 0 0;padding:7px 10px;border:1px dashed rgba(170,182,189,.5);border-radius:8px;color:#85777f;font-size:11px;line-height:1.55}
.fy-img-history{display:none!important}
@media(max-width:520px){.fy-memory{padding:10px 10px 11px;border-radius:13px}.fy-mem-table{font-size:10.5px}.fy-mem-table th,.fy-mem-table td{padding:4px 5px}}
/* XJX_MEMORY_END */
/* XJX_COT_START */
details.fy-cot{display:block;width:100%;max-width:480px;box-sizing:border-box;margin:10px 0 2px;padding:9px 12px 10px;border:1px solid rgba(170,182,189,.42);border-radius:13px;background:linear-gradient(145deg,rgba(255,255,255,.97),rgba(255,250,251,.94));box-shadow:0 10px 28px rgba(93,70,82,.10),inset 0 1px rgba(255,255,255,.9);color:#5e5058;font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif;font-size:11.5px;line-height:1.75;overflow-wrap:anywhere}
details.fy-cot>summary{list-style:none;cursor:pointer;user-select:none;margin:0 0 7px;padding:0 0 7px;border-bottom:1px dashed rgba(133,119,127,.28);font-weight:700;font-size:12px;letter-spacing:.05em;color:#7a8a93}
details.fy-cot>summary::-webkit-details-marker{display:none}
details.fy-cot>summary::after{content:"点击展开";margin-left:auto;font-size:10px;font-weight:600;color:#a9a2a8}
details.fy-cot[open]>summary::after{content:"收起"}
@media(max-width:520px){details.fy-cot{padding:8px 10px 9px;border-radius:11px;font-size:11px}details.fy-cot>summary{font-size:11px}}
/* XJX_COT_END */

/* XJX_FOLDBAN_START 防模型自加裸details包裹（禁令同时在提示词） */
details:not([class])>summary{display:none!important}
details:not([class]){display:contents!important}
/* XJX_FOLDBAN_END */

/* XJX_V2_ADDED_START */
.say{color:#d1537f;font-weight:600}
.msg{display:block;width:fit-content;max-width:86%;margin:7px 0 7px auto;padding:7px 11px;border-radius:14px 14px 4px 14px;background:linear-gradient(145deg,#ffe9f1,#ffd9e8);border:1px solid rgba(238,114,156,.35);color:#8f3f5e;font-size:13.5px;line-height:1.6}
.fy-s.fy-care{--fy-a:#8f7bd6}
.fy-ach{margin:8px 0 0;padding:7px 10px;border:1px dashed rgba(238,114,156,.45);border-radius:8px;background:rgba(255,240,246,.6);color:#a34a6b;font-size:11.5px;line-height:1.55;font-weight:600}
@media(max-width:520px){.msg{max-width:92%;font-size:12.5px}.fy-ach{font-size:10.5px}}
/* XJX_V2_ADDED_END */

/* XJX_V3_ADDED_START 三轴进度条 / 堕落条 / 三格分行 */
.fy-s .fy-g.fy-grow{grid-template-columns:1fr}
/* v2.7：单行布局下的格子允许自动换行，否则 nowrap+ellipsis 会把现金行的原因截断 */
.fy-s .fy-g.fy-grow span{white-space:normal;overflow:visible;text-overflow:clip;line-height:1.5}
.fy-bars{display:grid;grid-template-columns:1fr;gap:5px;margin:8px 0 0}
.fy-bar{display:flex;align-items:center;gap:7px;font-size:11px;line-height:1.2}
.fy-bar i{flex:none;width:2.4em;font-style:normal;font-weight:700;letter-spacing:.08em;color:#5e5058}
.fy-bar b{position:relative;flex:1;height:7px;border-radius:999px;background:rgba(130,108,119,.14);overflow:hidden}
.fy-bar b::after{content:"";position:absolute;inset:0 auto 0 0;width:0;border-radius:999px;background:var(--bar,#ee729c)}
.fy-bar em{flex:none;min-width:1.9em;font-style:normal;font-size:10.5px;font-weight:700;color:#85777f;text-align:right}
.fy-love{--bar:linear-gradient(90deg,#f7a8c4,#ee729c)}
.fy-lust{--bar:linear-gradient(90deg,#f7c48a,#f09045)}
.fy-deep{--bar:linear-gradient(90deg,#c3a6e8,#8f5fd6)}
.fy-corrupt{--bar:linear-gradient(90deg,#e06b8f,#b81f4a)}
.fy-bar b.fy-p0::after{width:0%}.fy-bar b.fy-p5::after{width:5%}.fy-bar b.fy-p10::after{width:10%}.fy-bar b.fy-p15::after{width:15%}.fy-bar b.fy-p20::after{width:20%}.fy-bar b.fy-p25::after{width:25%}.fy-bar b.fy-p30::after{width:30%}.fy-bar b.fy-p35::after{width:35%}.fy-bar b.fy-p40::after{width:40%}.fy-bar b.fy-p45::after{width:45%}.fy-bar b.fy-p50::after{width:50%}.fy-bar b.fy-p55::after{width:55%}.fy-bar b.fy-p60::after{width:60%}.fy-bar b.fy-p65::after{width:65%}.fy-bar b.fy-p70::after{width:70%}.fy-bar b.fy-p75::after{width:75%}.fy-bar b.fy-p80::after{width:80%}.fy-bar b.fy-p85::after{width:85%}.fy-bar b.fy-p90::after{width:90%}.fy-bar b.fy-p95::after{width:95%}.fy-bar b.fy-p100::after{width:100%}
.fy-fall{display:flex;align-items:center;gap:10px;box-sizing:border-box;width:100%;margin:12px 0 10px;padding:10px 14px;border:1px solid rgba(184,31,74,.30);border-radius:15px;background:linear-gradient(145deg,rgba(255,255,255,.97),rgba(255,245,248,.94));box-shadow:0 10px 28px rgba(93,70,82,.10),inset 0 1px rgba(255,255,255,.9);color:#463d43;font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif}
.fy-fall .fy-bar{flex:1}
.fy-fall .fy-bar i{color:#8d2742}
.fy-fallst{flex:none;font-size:11px;font-weight:700;color:#b81f4a;border:1px solid rgba(184,31,74,.35);border-radius:999px;padding:3px 9px;background:rgba(184,31,74,.07);white-space:nowrap}
@media(max-width:520px){.fy-bar{font-size:10.5px}.fy-fall{padding:9px 11px;border-radius:13px}}
.fy-state{display:none!important}
.fy-s.fy-n{--fy-a:#9aa7b0}
/* XJX_V3_ADDED_END */', '<!DOCTYPE html>
