}#xj-page #bgm:hover{background:var(--red);color:#fff;transform:translateY(-4px)}#xj-page #bgm.on{background:var(--red);color:#fff;border-color:var(--red)}#xj-page #bgm.on::after{content:'''';position:absolute;inset:-6px;border-radius:50%;border:1px solid rgba(176,65,62,.4);animation:bgmPulse 2.6s ease-out infinite;pointer-events:none}
@keyframes bgmPulse{0%{transform:scale(.92);opacity:.85}100%{transform:scale(1.38);opacity:0}}
@media (max-width:768px){#xj-page #bgm{right:16px;bottom:16px;width:40px;height:40px;font-size:16px}}#xj-page section{position:relative;z-index:2;padding:15vh 8vw}#xj-page .wrap{max-width:1080px;margin:0 auto;position:relative}#xj-page .kicker{
