}#xj-page .wm-light{color:rgba(255,255,255,.045)}#xj-page .wm-dark{color:rgba(61,58,56,.05)}#xj-page .orn{display:flex;align-items:center;gap:18px;margin:0 auto;max-width:420px;padding:8vh 0 0}#xj-page .orn span{flex:1;height:1px;background:linear-gradient(90deg,transparent,currentColor,transparent);opacity:.35}#xj-page .orn i{font-style:normal;font-size:15px;opacity:.6;animation:spin 9s linear infinite;display:inline-block}
@keyframes spin{to{transform:rotate(360deg)}}#xj-page .spark{position:absolute;font-style:normal;pointer-events:none;animation:tw 3.2s ease-in-out infinite}
@keyframes tw{0%,100%{opacity:.12;transform:scale(.7) rotate(0deg)}50%{opacity:.95;transform:scale(1.15) rotate(20deg)}}#xj-page .ribbon{
