@keyframes floaty{0%,100%{transform:translateY(0) rotate(0deg);opacity:.35}50%{transform:translateY(-16px) rotate(35deg);opacity:.8}}#xj-page .hero-kicker{font-size:12px;letter-spacing:.8em;font-weight:300;color:rgba(232,230,227,.55);margin-bottom:6vh}#xj-page .hero-name{
