}#xj-page .fc{position:absolute;will-change:transform;opacity:0}#xj-page .fc img{display:block;width:100%;height:auto}#xj-page .fc-in{animation:fc-in 2s cubic-bezier(.22,.61,.36,1) forwards}#xj-page .fc-in.d1{animation-delay:.25s}#xj-page .fc-in.d2{animation-delay:.5s}#xj-page .fc-in.d3{animation-delay:.75s}
