		<div id="summary-section" class="section">
			<h2 class="section-title">总结区</h2>
			<div id="summary-area"></div>
			<div id="copy-btn-container">
				<button id="copy-btn">
					<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5"
						stroke="currentColor">
						<path stroke-linecap="round" stroke-linejoin="round"
							d="M15.75 17.25v3.375c0 .621-.504 1.125-1.125 1.125h-9.75c-.621 0-1.125-.504-1.125-1.125V7.875c0-.621.504-1.125 1.125-1.125H6.75a9.06 9.06 0 0 1 1.5.124m7.5 10.376h3.375c.621 0 1.125-.504 1.125-1.125V11.25c0-4.56-3.69-8.25-8.25-8.25S4.5 6.69 4.5 11.25v6.75c0 .621.504 1.125 1.125 1.125h3.375m9.375-12.75H15v-2.25c0-.621-.504-1.125-1.125-1.125h-1.5c-.621 0-1.125.504-1.125 1.125v2.25m3.75 0h-3.75">
						</path>
					</svg>
					<span>一键复制</span>
				</button>
			</div>
		</div>


		<script>
			// JavaScript 部分
			document.addEventListener(''DOMContentLoaded'', () => {
				const openingLinesContainer = document.getElementById(''opening-lines-container'');
				const customInputDiv = document.getElementById(''custom-opening-line-input'');
				const generateBtn = document.getElementById(''generate-btn'');
				const summarySection = document.getElementById(''summary-section'');
				const summaryArea = document.getElementById(''summary-area'');
				const copyBtn = document.getElementById(''copy-btn'');

				// 开场白卡片选择效果
				openingLinesContainer.addEventListener(''change'', (e) => {
					if (e.target.name === ''opening-line'') {
						document.querySelectorAll(''.opening-line-card'').forEach(card => {
							card.classList.remove(''selected'');
						});
						const selectedCard = e.target.closest(''.opening-line-card'');
						if (selectedCard) {
							selectedCard.classList.add(''selected'');
						}

						if (e.target.value === ''custom'') {
							customInputDiv.style.display = ''block'';
						} else {
							customInputDiv.style.display = ''none'';
						}
					}
				});

				// 生成按钮点击事件
				generateBtn.addEventListener(''click'', () => {
					const playerName = document.getElementById(''player-name'').value || ''未设定'';
					const playerAge = document.getElementById(''player-age'').value || ''未设定'';
					const playerCharacter = document.getElementById(''player-character'').value || ''未设定'';
					const playerAppearance = document.getElementById(''player-appearance'').value || ''未设定'';
					const playerIdentity = document.getElementById(''player-identity'').value || ''未设定'';
					const playerDick = document.getElementById(''player-dick'').value || ''未设定'';
					const playerOther = document.getElementById(''player-other'').value || ''无'';

					let openingLine = '''';
					const selectedOpening = document.querySelector(''input[name="opening-line"]:checked'');
					if (selectedOpening) {
						if (selectedOpening.value === ''custom'') {
							openingLine = document.getElementById(''custom-opening-line-text'').value ||
								''（未设定自定义开场白）'';
						} else {
							openingLine = selectedOpening.value;
						}
					} else {
						openingLine = ''（未选择开场白）'';
					}

					const summaryContent = `
### 玩家设定
- 姓名： ${playerName}
- 年龄： ${playerAge}
- 性格：${playerCharacter}
- 外貌：${playerAppearance}
- 身份：${playerIdentity }
- 肉棒设定： ${playerDick}
- 其他设定： ${playerOther}

### 开场白
${openingLine}
                `;

					summaryArea.innerText = summaryContent.trim();
					summarySection.style.display = ''block'';
					summarySection.scrollIntoView({
						behavior: ''smooth''
					});
				});

				// 复制按钮点击事件
				copyBtn.addEventListener(''click'', () => {
					const textToCopy = summaryArea.innerText;
					navigator.clipboard.writeText(textToCopy).then(() => {
						const originalText = copyBtn.innerHTML;
						copyBtn.innerHTML = `
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor">
                          <path stroke-linecap="round" stroke-linejoin="round" d="M9 12.75 11.25 15 15 9.75M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
                        </svg>
                        <span>复制成功!</span>`;
						setTimeout(() => {
							copyBtn.innerHTML = originalText;
						}, 2000);
					}).catch(err => {
						console.error(''复制失败: '', err);
					});
				});
			});
		</script>


	</body>
</html>', '校园') ON CONFLICT (id) DO NOTHING;
