.c > details:nth-of-type(1) .s { color: #8b2626; }
.c > details:nth-of-type(2) .s { color: #3b5e47; }
.p { display: flex; align-items: center; gap: 8px; font-size: 12px; margin-top: 5px; color: #4a3b2c; }
.t { flex: 1; height: 10px; background: rgba(233,218,193,0.8); border-radius: 2px; box-shadow: inset 0 1px 5px rgba(0,0,0,0.1); border: 1px solid #d4c4a1; overflow: hidden; }
.f { height: 100%; border-radius: 0; background: linear-gradient(90deg, #a53232, #8b2626); box-shadow: none; }
.l div, .txt div, .lo div { padding: 8px 0; border-bottom: 1px dashed rgba(139,38,38,0.15); }
