.sb { margin: 10px 0; border: 1px solid rgba(139,38,38,0.2); background: #fdf6e3; border-radius: 2px; }
.sb > summary { background: #f4ebd0 !important; color: #4a3b2c !important; font-size: 14px; padding: 8px 12px; text-shadow: none; border-bottom: 1px solid rgba(139,38,38,0.2); border-radius: 2px; }
.in { padding: 10px 12px; font-size: 14px; line-height: 1.8; }
.c > details:nth-of-type(1) .in { color: #2c2216; }
.c > details:nth-of-type(2) .in { color: #2c4234; }
.md { background: #f4ebd0; padding: 12px; border-radius: 2px; color: #4a3b2c; margin-top: 10px; border-left: 4px solid #8b2626; font-style: italic; box-shadow: inset 0 0 15px rgba(0,0,0,0.02); }
