INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_twin_idols_fiancee', 'deck_twin_idols_fiancee', '国民级顶流双胞胎偶像转校生是我的未婚妻？', '国民双子 · 婚约转校', 'bg-purple-950/90 text-purple-300 border-purple-600/60', '吃花生的瓜子', '夏梦瑶与夏梦璃，舞台上风靡全国的顶流双子偶像，竟同时空降转校到了你的班级，并双双宣布是你的法定未婚妻！端庄清冷的姐姐与俏皮腹黑的小恶魔妹妹，两张绝美相同的容颜下，拉开了一场极限修罗场争宠战。', '9.9', '["双胞胎", "偶像", "未婚妻", "修罗场", "校园", "后宫", "二次元"]', '124.6k 玩过 · 39.2k 深度', 2, '2026-09-16 11:22:22', 'https://catai.wiki/4e84457e-3995-4aa8-7443-aa9e61ae8400/cover', NULL, 'fire', 1, '校园') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_brother_loli_girlfriend', 'deck_brother_loli_girlfriend', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', 'bg-amber-950/90 text-amber-300 border-amber-600/60', '倒霉狐', '你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。', '9.8', '["NTR", "巨乳萝莉", "调教", "凌辱", "背德", "破甲", "开局即可色"]', '98.7k 玩过 · 31.5k 深度', 3, '2026-09-16 11:22:22', 'https://catai.wiki/87c12f5e-6807-4376-6c17-d4ec43aec500/cover', NULL, 'fire', 1, '都市') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_white_tiger_sister_night', 'deck_white_tiger_sister_night', '巨乳白虎妹妹每晚夜袭肥鲍迷奸', '白虎夜袭 · 禁断共犯', 'bg-rose-950/90 text-rose-300 border-rose-600/60', 'HQAZXSW', '白天在学校里高冷清傲、对你冷漠如陌生人的顶级校花妹妹林溪月，却在深夜等全家寂静后，悄悄钻进你的被窝，跨上你熟睡的身体，用天生白虎的湿润蜜穴摩擦你的坚挺……一场彼此秘而不宣的共犯沉沦。', '9.9', '["巨乳妹妹", "白虎", "夜袭", "迷奸", "已破甲", "调教", "同居", "禁忌恋"]', '112.4k 玩过 · 36.8k 深度', 4, '2026-09-16 11:22:22', 'https://catai.wiki/91501982-46e5-4411-913b-9ee77d823a00/cover', NULL, 'fire', 1, '都市') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_grade_first_demands', 'deck_grade_first_demands', '成绩至上主义学园：不得拒绝年级第一的任何要求', '成绩至上 · 绝对命令', 'bg-red-950/90 text-red-300 border-red-600/60', 'kaaa0101', '全封闭私立极道学园，分数代表一切特权。作为稳坐年级第一的唯一天花板，你拥有凌驾一切校规的绝对命令权——上至知性丰满的女教师、优雅威严的女校长，下至傲慢名媛校花，都不得拒绝你的任何要求！', '9.9', '["成绩至上", "绝对命令", "女教师", "女校长", "校花", "后宫", "调教", "破甲"]', '143.2k 玩过 · 48.6k 深度', 5, '2026-09-16 11:22:22', 'https://catai.wiki/d16727cf-079f-4342-3489-c05325d0c700/cover', NULL, 'fire', 1, '校园') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_mysterious_recovery_ghost', 'deck_mysterious_recovery_ghost', '神秘复苏（是人亦是鬼）', '神秘复苏 · 诡异驭鬼', 'bg-slate-950/90 text-emerald-300 border-emerald-700/50', '海豹大人', '五浊恶世，地狱已空，厉鬼复苏，唯有以鬼制鬼！完美还原《神秘复苏》世界观与绝望灵异法则。敲门声在教室走廊响起，惨绿鬼烛在风中摇曳，你将在鬼域与厉鬼的索命规则中求生，寻找契机驾驭诡异。', '9.8', '["神秘复苏", "诡异", "开放世界", "自由探索", "灵异", "驭鬼者", "破甲"]', '89.1k 玩过 · 27.4k 深度', 6, '2026-09-16 11:22:22', 'https://catai.wiki/61775def-9314-488c-7d6a-2a90d4711e00/cover', NULL, 'fire', 1, '玄幻') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, created_at, cover_image, image_tag, badge_type, is_featured, category) VALUES ('deck_mouth_feed_sister', 'deck_mouth_feed_sister', '嘴对着喂你的巨乳肥臀姐姐', '真空姐姐 · 口渡喂食', 'bg-orange-950/90 text-orange-300 border-orange-600/60', 'ed11020', '父母常年在外，家里只有你和慵懒的H罩杯巨乳姐姐林夏。她在家从来不穿内裤，真空套着宽松露肩衬衫晃来晃去；懒得吃饭就嘴对嘴把食物渡给你。用一整个炎热夏日考验着弟弟的极限定力！', '9.9', '["巨乳姐姐", "纯爱", "日常同居", "不穿内裤", "已破甲", "擦边定力考验"]', '136.8k 玩过 · 45.1k 深度', 7, '2026-09-16 11:22:22', 'https://catai.wiki/9975ca9d-d1d3-4d9f-824f-beda00076300/cover', NULL, 'fire', 1, '日常') ON CONFLICT (title) DO NOTHING;
