INSERT INTO conversations (id, user_id, deck_id, deck_title, title, history_json, turn_count, created_at, updated_at) VALUES ('conv_1789308235527', 'user_master', 'deck_eri_summer', '夏蝉之骨 · 白石绘梨', '奥木川老宅 · 临庭院的旧榻榻米居室 · 午后 14:15', '[{"isUser": false, "model": "deepseek-v3.2", "location": "奥木川老宅 · 临庭院的旧榻榻米居室 · 午后 14:15", "story": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。\n\n庭院里的夏蝉嘶鸣得近乎凄厉。\n\n白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属于你的宽大纯白旧T恤，领口松垮地倾斜在一侧，露出一整片苍白得近乎透明的优美锁骨与后颈细小的淡青色血管。\n\n屋里没有开空调，只有她身上淡淡的草木冷香与浅浅的汗意。\n\n她将脸颊紧紧贴在你的大腿布料上，纤细得仿佛稍一用力就会折断的手指，死死揪着你的衣角。冰凉的脚尖下意识地往你的裤管边试探着缩了缩。\n\n「哥哥……」\n\n她细弱的声音像游丝般贴着席面飘进你的耳膜，黑发遮掩下的深褐色双眸泛着病态的执拗与依附：\n\n「刚才大伯打电话来说……想让我们分开去不同的亲戚家寄宿……」\n她的手指猛地掐紧，指甲几乎陷进你的血肉里，呼吸急促得像要碎裂，\n「哥哥……你会扔下我吗？如果……如果连哥哥也不要我了，我就去后山的蓄水池跳下去……」", "memory": ["双亲葬礼后的一周，你与绘梨拒绝了所有亲戚的收养，躲回了与世隔绝的奥木川乡下老屋", "绘梨患有严重的重度分离焦虑与选择性缄默，唯一能让她感到安全的是贴着哥哥的身体与气味"], "status": {"clothes": "洗旧宽大男士白T恤 / 锁骨大面积露白 / 光脚", "posture": "像小动物般蜷缩在主角膝侧，手指死死揪紧衣角", "stats": "病态依恋度: 96% | 情绪稳定度: 25% (极易崩溃)", "risk": "随时可能做出极端排他性自残举动"}, "branches": [{"tag": "A", "title": "紧紧将她搂入怀中", "desc": "伸手环住她单薄冰凉的后背，用下巴抵着她的发旋，斩钉截铁地向她承诺绝对不会分开"}, {"tag": "B", "title": "揉她的发丝并安抚", "desc": "轻抚她微乱细软的黑发，取出切好的冰镇西瓜递到她嘴边，转移她的焦虑"}, {"tag": "C", "title": "握住她冰凉的脚踝", "desc": "拉过薄毛毯盖住她裸露的腿，沉下声音轻斥她不许胡思乱想，命令她看着你的眼睛"}, {"tag": "D", "title": "切断座机电话线", "desc": "当着她的面拔掉老宅的电话线，告诉她：这个世界上除了我们俩，任何人的话都不作数"}]}]', 1, '2026-09-13 22:03:55', '2026-09-13 22:03:55') ON CONFLICT (id) DO NOTHING;
